return {
  name: 'novel-assistant-host',
  apply(ctx) {
    const fs = ctx.get('fs')
    const sp = ctx.get('sandboxPolicy')
    if (fs === undefined || sp === undefined) return
    let seq = 0
    let loaded = false
    let rootCache = null
    const uid = (p) => p + (++seq)
    const clock = () => { try { return new Date().toISOString() } catch (e) { return '#' + (++seq) } }
    let state = {
      meta: { title: '', premise: '', genre: '', tone: '', targetLength: '', updatedAt: '' },
      settings: [],
      plot: { events: [] },
      seeds: [],
      outline: { arcs: [] },
      log: [],
    }
    function findSession() {
      try {
        const agents = ctx.get('agents')
        if (!agents) return null
        const list = agents.list()
        for (const a of list) {
          const s = a.session || (a.ctx && a.ctx.session)
          if (s && s.meta && typeof s.meta.cwd === 'string' && s.meta.cwd) return s
        }
        return null
      } catch (e) { return null }
    }
    function policyForSession(session) {
      try {
        if (!session) return undefined
        const resolved = sp.resolve({ session: session })
        return resolved || undefined
      } catch (e) { return undefined }
    }
    function sessionCwd() {
      try {
        const agents = ctx.get('agents')
        if (!agents) return null
        const agent = agents.currentInitiator()
        if (!agent) return null
        if (typeof agent.cwd === 'string' && agent.cwd) return agent.cwd
        if (agent.session && agent.session.meta && typeof agent.session.meta.cwd === 'string' && agent.session.meta.cwd) return agent.session.meta.cwd
        if (agent.ctx && agent.ctx.session && agent.ctx.session.meta && typeof agent.ctx.session.meta.cwd === 'string' && agent.ctx.session.meta.cwd) return agent.ctx.session.meta.cwd
        if (typeof agent.sessionId === 'string') {
          const sessions = ctx.get('sessions')
          const s = sessions && sessions.get(agent.sessionId)
          if (s && s.meta && typeof s.meta.cwd === 'string' && s.meta.cwd) return s.meta.cwd
        }
        return null
      } catch (e) { return null }
    }
    function trimSlash(p) {
      while (p.length > 1 && (p.endsWith('/') || p.endsWith('\\'))) p = p.slice(0, -1)
      return p
    }
    async function readPointer() {
      try {
        const target = await fs.resolve('novel-assistant/.root', { cwd: sp.workspaceRoot || '.' })
        const info = await fs.stat(target)
        if (!info) return null
        const text = (await fs.readText(target)).trim()
        return text ? text : null
      } catch (e) { return null }
    }
    async function resolveRoot() {
      if (rootCache) return rootCache
      const cwd = sessionCwd()
      if (cwd) { rootCache = trimSlash(cwd); return rootCache }
      try {
        const probe = await fs.resolve('novel-assistant/state.json')
        const info = await fs.stat(probe)
        if (info) {
          const p = fs.processPath(probe)
          const idx = p.indexOf('novel-assistant')
          if (idx > 0) { rootCache = trimSlash(p.slice(0, idx)); return rootCache }
        }
      } catch (e) {}
      const ptr = await readPointer()
      if (ptr) { rootCache = trimSlash(ptr); return rootCache }
      rootCache = sp.workspaceRoot || '.'
      return rootCache
    }
    function rebuildSeq() {
      let max = 0
      const walk = (list) => list.forEach((o) => { const m = /(\d+)$/.exec(o.id || ''); if (m) { const n = parseInt(m[1], 10); if (n > max) max = n } })
      walk(state.settings)
      walk(state.plot.events)
      walk(state.seeds)
      state.outline.arcs.forEach((a) => { walk([a]); walk(a.chapters || []) })
      seq = max
    }
    async function ensureLoaded() {
      if (loaded) return
      loaded = true
      try {
        const root = await resolveRoot()
        const target = await fs.resolve(root + '/novel-assistant/state.json')
        const info = await fs.stat(target)
        if (info) {
          const parsed = JSON.parse(await fs.readText(target))
          if (parsed && parsed.meta) {
            state = parsed
            if (!state.settings) state.settings = []
            if (!state.plot) state.plot = { events: [] }
            if (!state.seeds) state.seeds = []
            if (!state.outline) state.outline = { arcs: [] }
            if (!state.log) state.log = []
            rebuildSeq()
          }
        }
      } catch (e) {
        console.error('[novel-assistant] load failed:', e && e.message)
      }
    }
    function pushLog(tool, note) {
      state.log.push({ at: clock(), tool: tool, note: note })
      if (state.log.length > 200) state.log.shift()
    }
    async function writeWithPolicy(relPath, content) {
      const root = await resolveRoot()
      const target = await fs.resolve(root + '/novel-assistant/' + relPath)
      const session = findSession()
      const policy = policyForSession(session)
      try {
        await fs.writeText(target, content, undefined, undefined, policy)
      } catch (e) {
        await fs.writeText(target, content, undefined, undefined, { mode: 'danger-full-access', workspaceRoot: root })
      }
      return target
    }
    async function persist() {
      try {
        await ensureLoaded()
        state.meta.updatedAt = clock()
        await writeWithPolicy('state.json', JSON.stringify(state, null, 2))
      } catch (e) {
        console.error('[novel-assistant] persist failed:', e && e.message)
      }
    }
    const SETTING_TYPES = ['world', 'character', 'faction', 'power', 'location', 'item', 'timeline', 'other']
    const EVENT_TYPES = ['开端', '发展', '转折', '高潮', '收束', '结局', '支线', '其他']
    const STATUSES = ['committed', 'candidate', 'rejected']
    const SEED_STATUSES = ['planted', 'growing', 'payoff', 'abandoned']
    const SEED_HORIZONS = ['短', '中', '长', '超长']
    function findSetting(id) { return state.settings.find((s) => s.id === id) }
    function findEvent(id) { return state.plot.events.find((e) => e.id === id) }
    function findSeed(id) { return state.seeds.find((s) => s.id === id) }
    function render(_a, v) {
      return [{ type: 'text', text: typeof v === 'string' ? v : JSON.stringify(v, null, 2) }]
    }
    function registerTool(def) { harness.registerTool(ctx, harness.defineTool(def)) }
    function computeLayout() {
      const warnings = []
      const entities = {}
      state.settings.forEach((s) => {
        const entry = { id: s.id, name: s.name, type: s.type, state: {}, relations: (s.relations || []).slice() }
        ;(s.fields || []).forEach((f) => {
          const i = f.indexOf('：')
          if (i > 0) entry.state[f.slice(0, i).trim()] = f.slice(i + 1).trim()
          else if (i === -1) { const j = f.indexOf(':'); if (j > 0) entry.state[f.slice(0, j).trim()] = f.slice(j + 1).trim() }
        })
        entities[s.id] = entry
      })
      state.plot.events.filter((e) => e.status === 'committed').forEach((ev) => {
        ;(ev.world_delta || []).forEach((d) => {
          const m = /^([^:]+):([^:]+):(.*?)→(.*)$/.exec(d)
          if (!m) { warnings.push(ev.id + ' 无法解析的 world_delta：「' + d + '」'); return }
          const id = m[1].trim(), field = m[2].trim(), from = m[3].trim(), to = m[4].trim()
          const entry = entities[id]
          if (!entry) { warnings.push(ev.id + ' world_delta 指向不存在的设定 ' + id); return }
          const cur = entry.state[field]
          if (cur !== undefined && from && cur !== from) warnings.push(ev.id + ' world_delta 失配 ' + id + '.' + field + '：当前「' + cur + '」≠ 旧值「' + from + '」')
          entry.state[field] = to
        })
      })
      const pairMap = {}
      state.plot.events.filter((e) => e.status === 'committed').forEach((e) => {
        const b = e.conflict_between || []
        for (let i = 0; i < b.length; i++) {
          for (let j = i + 1; j < b.length; j++) {
            const key = [b[i], b[j]].sort().join('|')
            pairMap[key] = pairMap[key] || { a: b[i], b: b[j], events: [], count: 0 }
            pairMap[key].events.push(e.id)
            pairMap[key].count++
          }
        }
      })
      const conflicts = Object.keys(pairMap).map((k) => ({ pair: [pairMap[k].a, pairMap[k].b], events: pairMap[k].events, count: pairMap[k].count }))
      const factionMembers = {}
      state.settings.forEach((s) => {
        if (s.type !== 'faction') return
        const members = []
        state.settings.forEach((o) => {
          if (o.type !== 'character') return
          const linked = (o.relations || []).some((r) => r.indexOf(s.id + ' ') === 0 || r.indexOf(s.id + '：') === 0 || r.indexOf(s.id) === 0)
          if (linked) members.push(o.id)
        })
        factionMembers[s.id] = members
      })
      return { entities: entities, conflicts: conflicts, factionMembers: factionMembers, warnings: warnings }
    }
    registerTool({
      name: 'novel_init',
      description: '创建或重置小说项目（会覆盖当前项目）。这是项目的起点：只接收构思（标题+一句话核心构思），不接收正文。创建后按 设定→推演→大纲 顺序推进。',
      parameters: {
        title: { type: 'string', required: true, description: '作品名' },
        premise: { type: 'string', required: true, description: '一句话核心构思：主角、核心冲突、世界基调。结构化描述，非文学段落' },
        genre: { type: 'string', description: '题材，如 玄幻/科幻/悬疑/都市/武侠' },
        tone: { type: 'string', description: '风格基调，如 热血/冷峻/诙谐' },
        target_length: { type: 'string', description: '目标篇幅，如 200万字 或 中篇' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const oldTitle = state.meta.title
        state = {
          meta: { title: args.title, premise: args.premise, genre: args.genre || '', tone: args.tone || '', targetLength: args.target_length || '', updatedAt: clock() },
          settings: [],
          plot: { events: [] },
          seeds: [],
          outline: { arcs: [] },
          log: [],
        }
        pushLog('novel_init', '创建项目：' + args.title)
        await persist()
        return '项目已创建：《' + args.title + '》' + (oldTitle ? '（覆盖了原项目《' + oldTitle + '》）' : '') +
          '\n核心构思：' + args.premise +
          '\n下一步：先用 novel_setting_upsert 建立世界观与核心人物（type=world / character），再开始推演。'
      },
    })
    registerTool({
      name: 'novel_state',
      description: '读取当前项目状态，用于推演前的上下文检索。view=overview 返回精简总览（含存储根目录 store 与伏笔统计）；view=settings 返回设定列表（可按 type/query 过滤）；view=plot 返回完整事件链；view=seeds 返回伏笔列表；view=outline 返回大纲；view=full 返回全部。',
      parameters: {
        view: { type: 'string', description: 'overview|settings|plot|seeds|outline|full，默认 overview' },
        type: { type: 'string', description: 'settings 视图下按类型过滤：world/character/faction/power/location/item/timeline/other' },
        query: { type: 'string', description: '按名称关键字过滤设定' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const view = args.view || 'overview'
        if (view === 'overview') {
          return JSON.stringify({
            meta: state.meta,
            store: await resolveRoot(),
            stats: {
              settings: state.settings.length,
              events: state.plot.events.length,
              committed: state.plot.events.filter((e) => e.status === 'committed').length,
              candidates: state.plot.events.filter((e) => e.status === 'candidate').length,
              seeds: state.seeds.length,
              seedsOpen: state.seeds.filter((s) => s.status === 'planted' || s.status === 'growing').length,
              arcs: state.outline.arcs.length,
            },
            chain: state.plot.events.filter((e) => e.status === 'committed').map((e) => e.id + ' ' + e.type + ' ' + e.title),
            pending: state.plot.events.filter((e) => e.status === 'candidate').map((e) => ({ id: e.id, title: e.title, branchOf: e.branch_of })),
          }, null, 2)
        }
        if (view === 'settings') {
          let list = state.settings
          if (args.type) list = list.filter((s) => s.type === args.type)
          if (args.query) list = list.filter((s) => (s.name || '').indexOf(args.query) >= 0 || (s.summary || '').indexOf(args.query) >= 0)
          return JSON.stringify({ count: list.length, settings: list }, null, 2)
        }
        if (view === 'plot') {
          return JSON.stringify({ events: state.plot.events }, null, 2)
        }
        if (view === 'seeds') {
          return JSON.stringify({ count: state.seeds.length, seeds: state.seeds }, null, 2)
        }
        if (view === 'outline') {
          return JSON.stringify({ arcs: state.outline.arcs }, null, 2)
        }
        return JSON.stringify(state, null, 2)
      },
    })
    registerTool({
      name: 'novel_store',
      description: '查看或设置项目存储根目录。默认自动解析：会话工作区（cwd）→ fs 默认基路径探测 → .root 指针文件 → 沙箱回退根。当自动解析不对时，用 action=set root=绝对路径 显式指定（会写入 <回退根>/novel-assistant/.root 指针，供以后会话复用）。',
      parameters: {
        action: { type: 'string', enum: ['report', 'set'], description: 'report=输出诊断；set=设置存储根目录（需 root 参数）' },
        root: { type: 'string', description: '绝对路径，仅 action=set 时必填' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        if (args.action === 'set') {
          if (!args.root || !/^[a-zA-Z]:[\\/]|^\\/.test(args.root)) return 'root 必须是绝对路径：' + args.root
          rootCache = trimSlash(args.root)
          try {
            const target = await fs.resolve('novel-assistant/.root', { cwd: sp.workspaceRoot || '.' })
            await fs.writeText(target, rootCache)
            await persist()
            return '存储根目录已设为：' + rootCache + '（指针已写入 ' + fs.processPath(target) + '）'
          } catch (e) {
            await persist()
            return '存储根目录已设为（本次会话）：' + rootCache + '；但指针写入失败：' + ((e && e.message) || e)
          }
        }
        const session = findSession()
        let policyInfo = null
        try {
          const p = policyForSession(session)
          if (p) policyInfo = { mode: p.mode, workspaceRoot: p.workspaceRoot }
        } catch (e) {}
        let defaultBase = null
        try { defaultBase = fs.processPath(await fs.resolve('.')) } catch (e) {}
        return JSON.stringify({
          workspaceRoot: sp.workspaceRoot || '.',
          fsDefaultBase: defaultBase,
          sessionCwd: sessionCwd(),
          sessionFoundCwd: session && session.meta ? session.meta.cwd : null,
          sessionPolicy: policyInfo,
          currentRoot: await resolveRoot(),
        }, null, 2)
      },
    })
    registerTool({
      name: 'novel_setting_upsert',
      description: '新建或更新一条设定卡。设定是推演的“铁律”：之后提交的事件不得与设定冲突。id 省略时新建；id 存在时更新该卡。type 必填：world 世界观 / character 人物 / faction 势力 / power 力量体系 / location 地点 / item 物品 / timeline 时间线 / other 其他。fields 每项格式 “键：值”；relations 每项格式 “目标id 关系描述”（如 “c1 是 c2 的师父”）。',
      parameters: {
        id: { type: 'string', description: '设定卡 id（省略=新建）' },
        type: { type: 'string', required: true, description: 'world/character/faction/power/location/item/timeline/other' },
        name: { type: 'string', required: true, description: '名称' },
        summary: { type: 'string', description: '一句话概述（能力、立场、作用等结构化信息）' },
        fields: { type: 'array', items: { type: 'string' }, description: '键值对数组，每项 “键：值”' },
        relations: { type: 'array', items: { type: 'string' }, description: '关系数组，每项 “目标id 关系描述”' },
        tags: { type: 'array', items: { type: 'string' }, description: '标签数组' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        if (SETTING_TYPES.indexOf(args.type) < 0) return '未知设定类型：' + args.type + '，可选：' + SETTING_TYPES.join('/')
        let card = args.id ? findSetting(args.id) : null
        if (args.id && !card) return '设定不存在：' + args.id
        if (!card) {
          card = { id: uid('s'), type: args.type, name: args.name, summary: args.summary || '', fields: [], relations: [], tags: [] }
          state.settings.push(card)
          pushLog('novel_setting_upsert', '新建设定 ' + card.id + ' ' + card.name + ' (' + args.type + ')')
        } else {
          pushLog('novel_setting_upsert', '更新设定 ' + card.id + ' ' + card.name)
        }
        card.type = args.type
        card.name = args.name
        if (args.summary !== undefined) card.summary = args.summary
        if (args.fields) card.fields = args.fields.slice()
        if (args.relations) card.relations = args.relations.slice()
        if (args.tags) card.tags = args.tags.slice()
        await persist()
        return '设定已保存：' + card.id + ' ' + card.name + '（' + card.type + '）'
      },
    })
    registerTool({
      name: 'novel_setting_remove',
      description: '删除一条设定卡。删除前先检查事件链中是否还有引用。',
      parameters: {
        id: { type: 'string', required: true, description: '设定卡 id' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const idx = state.settings.findIndex((s) => s.id === args.id)
        if (idx < 0) return '设定不存在：' + args.id
        const refs = state.plot.events.filter((e) =>
          (e.participants || []).indexOf(args.id) >= 0 || (e.constraints || []).indexOf(args.id) >= 0 || (e.location || '') === args.id)
        state.settings.splice(idx, 1)
        pushLog('novel_setting_remove', '删除设定 ' + args.id + (refs.length ? '（仍有 ' + refs.length + ' 个事件引用，建议先用 novel_plot_amend 修正）' : ''))
        await persist()
        return '已删除设定 ' + args.id + (refs.length ? '。注意：' + refs.length + ' 个事件仍引用它，请用 novel_plot_amend 修正。' : '')
      },
    })
    registerTool({
      name: 'novel_seed_upsert',
      description: '新建或更新一条剧情伏笔。伏笔是长篇布局的核心：埋设(planted)→悬置成长(growing)→回收(payoff)→放弃(abandoned)。id 省略时新建。intent 写清“为何埋设、何时如何回收、反转点是什么”。horizon 是回收距离（短/中/长/超长）。visibility=reader 明线（读者可见）/hidden 暗线（读者不觉）。planted_at/payoff_at 关联具体事件 id，related_settings/related_events 关联设定与事件。',
      parameters: {
        id: { type: 'string', description: '伏笔 id（省略=新建）' },
        title: { type: 'string', required: true, description: '伏笔名称（一句话，如 “焚天残魂隐瞒真正的复活条件”）' },
        status: { type: 'string', enum: ['planted', 'growing', 'payoff', 'abandoned'], description: '状态：已埋设/悬置成长/已回收/已放弃，默认 planted' },
        horizon: { type: 'string', enum: ['短', '中', '长', '超长'], description: '回收距离，默认 中' },
        intent: { type: 'string', description: '伏笔意图：为何埋设、何时回收、反转点' },
        visibility: { type: 'string', enum: ['reader', 'hidden'], description: 'reader=明线（读者可见）；hidden=暗线，默认 reader' },
        planted_at: { type: 'string', description: '埋设事件 id' },
        payoff_at: { type: 'string', description: '回收事件 id（设置后建议把 status 改为 payoff）' },
        related_settings: { type: 'array', items: { type: 'string' }, description: '关联设定 id' },
        related_events: { type: 'array', items: { type: 'string' }, description: '关联事件 id' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        if (SEED_STATUSES.indexOf(args.status || 'planted') < 0) return '未知状态：' + args.status
        if (args.horizon && SEED_HORIZONS.indexOf(args.horizon) < 0) return '未知回收距离：' + args.horizon
        if (args.planted_at && !findEvent(args.planted_at)) return '埋设事件不存在：' + args.planted_at
        if (args.payoff_at && !findEvent(args.payoff_at)) return '回收事件不存在：' + args.payoff_at
        let seed = args.id ? findSeed(args.id) : null
        if (args.id && !seed) return '伏笔不存在：' + args.id
        if (!seed) {
          seed = { id: uid('f'), title: args.title, status: 'planted', horizon: '中', intent: '', visibility: 'reader', planted_at: '', payoff_at: '', related_settings: [], related_events: [] }
          state.seeds.push(seed)
          pushLog('novel_seed_upsert', '埋设伏笔 ' + seed.id + ' ' + seed.title)
        } else {
          pushLog('novel_seed_upsert', '更新伏笔 ' + seed.id + ' ' + seed.title)
        }
        seed.title = args.title
        seed.status = args.status || seed.status
        if (args.horizon) seed.horizon = args.horizon
        if (args.intent !== undefined) seed.intent = args.intent
        if (args.visibility) seed.visibility = args.visibility
        if (args.planted_at !== undefined) seed.planted_at = args.planted_at
        if (args.payoff_at !== undefined) seed.payoff_at = args.payoff_at
        if (args.related_settings) seed.related_settings = args.related_settings.slice()
        if (args.related_events) seed.related_events = args.related_events.slice()
        await persist()
        return '伏笔已保存：' + seed.id + '「' + seed.title + '」（' + seed.status + '，' + (seed.horizon || '中') + '回收，' + (seed.visibility === 'hidden' ? '暗线' : '明线') + '）'
      },
    })
    registerTool({
      name: 'novel_seed_remove',
      description: '删除一条伏笔。',
      parameters: {
        id: { type: 'string', required: true, description: '伏笔 id' },
      },
      output: { schema: { type: 'string' }, render: render },
      async execute(args) {
        await ensureLoaded()
        const idx = state.seeds.findIndex((s) => s.id === args.id)
