      if (seed.horizon && SEED_HORIZONS.indexOf(seed.horizon) < 0) return { ok: false, message: '未知回收距离：' + seed.horizon }
      if (seed.planted_at && !findEvent(seed.planted_at)) return { ok: false, message: '埋设事件不存在：' + seed.planted_at }
      if (seed.payoff_at && !findEvent(seed.payoff_at)) return { ok: false, message: '回收事件不存在：' + seed.payoff_at }
      let s = seed.id ? findSeed(seed.id) : null
      if (seed.id && !s) return { ok: false, message: '伏笔不存在：' + seed.id }
      if (!s) {
        s = { id: uid('f'), title: seed.title, status: 'planted', horizon: '中', intent: '', visibility: 'reader', planted_at: '', payoff_at: '', related_settings: [], related_events: [] }
        state.seeds.push(s)
        pushLog('seed-save', '面板埋设伏笔 ' + s.id)
      } else {
        pushLog('seed-save', '面板更新伏笔 ' + s.id)
      }
      s.title = seed.title
      if (seed.status) s.status = seed.status
      if (seed.horizon) s.horizon = seed.horizon
      if (seed.intent !== undefined) s.intent = seed.intent
      if (seed.visibility) s.visibility = seed.visibility
      if (seed.planted_at !== undefined) s.planted_at = seed.planted_at
      if (seed.payoff_at !== undefined) s.payoff_at = seed.payoff_at
      if (seed.related_settings) s.related_settings = seed.related_settings.slice()
      if (seed.related_events) s.related_events = seed.related_events.slice()
      await persist()
      return { ok: true, id: s.id }
    })
    harness.handle('seed-remove', async (args) => {
      await ensureLoaded()
      const id = args && args.id
      const idx = state.seeds.findIndex((s) => s.id === id)
      if (idx < 0) return { ok: false, message: '伏笔不存在：' + id }
      state.seeds.splice(idx, 1)
      pushLog('seed-remove', '面板删除伏笔 ' + id)
      await persist()
      return { ok: true }
    })
    harness.handle('plot-decide', async (args) => {
      await ensureLoaded()
      const ev = findEvent(args && args.eventId)
      if (!ev) return { ok: false, reason: '事件不存在：' + (args && args.eventId) }
      if (args.accept) {
        ev.status = 'committed'
        const siblings = state.plot.events.filter((e) => e.branch_of === ev.branch_of && e.id !== ev.id && e.status === 'candidate')
