        pushLog('plot-decide', '面板采纳 ' + ev.id + (siblings.length ? '，否决 ' + siblings.map((s) => s.id).join('、') : ''))
        await persist()
        return { ok: true, accepted: ev.id, rejected: siblings.map((s) => s.id) }
      }
      ev.status = 'rejected'
      pushLog('plot-decide', '面板否决 ' + ev.id)
      await persist()
      return { ok: true, rejected: ev.id }
    })
  },
}

